#!/usr/bin/env python3
from __future__ import annotations
import html, json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
RESULTS=ROOT/"receipts/results"

def load(name): return json.loads((RESULTS/name).read_text())
def pct(x): return f"{x*100:.1f}%"

def main():
 typed=load("typed-decisions.summary.json"); phish=load("phishing.summary.json"); jevb=load("jevbench-public.summary.json")
 btz=load("btzsc.summary.json"); review=load("code-review.summary.json"); clash=load("clash.summary.json")
 rows=[
  ("Typed decisions",typed["metrics"]["accuracy"],typed["jev_reference"]["accuracy"],"2,000 decisions","Aggregate / unpaired"),
  ("PhishNChips",phish["metrics"]["accuracy"],phish["jev_reference"]["accuracy"],"2,000 emails","Aggregate / unpaired"),
  ("JevBench public",jevb["metrics"]["jev48_accuracy"],jevb["metrics"]["jev_accuracy"],"231 tasks","Paired outcomes"),
  ("BTZSC pilot",btz["metrics"]["jev48_accuracy"],btz["metrics"]["jev_accuracy"],"300 texts","Aggregate / unpaired"),
  ("Code review",review["metrics"]["jev48_accuracy"],review["metrics"]["jev_accuracy"],"480 rule decisions","Repeated Jev reference"),
  ("CLASH conflicts",clash["metrics"]["jev48_accuracy"],clash["metrics"]["jev_accuracy"],"1,289 cases","Aggregate / unpaired"),
 ]
 total=sum(int(''.join(c for c in n if c.isdigit())) for *_,n,_ in rows)
 wins=sum(a>b for _,a,b,_,_ in rows); ties=sum(abs(a-b)<1e-12 for _,a,b,_,_ in rows)
 table=''.join(f'''<article class="bench"><div class="bench-top"><div><span class="kicker">{html.escape(scope)}</span><h3>{html.escape(name)}</h3></div><div class="delta {'up' if ours>jev else 'down' if ours<jev else ''}">{(ours-jev)*100:+.1f} pts</div></div><div class="lane"><span>Jev48</span><div class="track"><i class="ours" style="width:{ours*100:.3f}%"></i></div><b>{pct(ours)}</b></div><div class="lane"><span>Jev</span><div class="track"><i style="width:{jev*100:.3f}%"></i></div><b>{pct(jev)}</b></div><p>{html.escape(note)}</p></article>''' for name,ours,jev,scope,note in rows)
 html_doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Jev48 benchmark — AGI Labs</title><meta name="description" content="Six public benchmarks. One open 2B decision model. Every result, favorable or not."><meta property="og:title" content="Jev48: six public Jev benchmarks"><meta property="og:description" content="Every eligible reproducible public suite. Receipts and code included."><meta property="og:image" content="https://agilabs.cc/jev48/benchmark-ranking.png"><meta name="twitter:card" content="summary_large_image"><style>
:root{{--bg:#fff;--ink:#050505;--muted:#6b6b6b;--soft:#f6f6f6;--line:#e5e5e5;--blue:#154cff;--blue-soft:#eef3ff;--font:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;--mono:"SFMono-Regular",Consolas,"Liberation Mono",monospace;--radius:9px;--page:1080px}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;color:var(--ink);font:15px/1.5 var(--font);font-variant-numeric:tabular-nums}}a{{color:inherit;text-decoration:none}}.wrap{{width:min(var(--page),calc(100% - 56px));margin:auto}}.nav{{height:85px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}}.brand{{display:flex;align-items:center;gap:9px;font-size:22px;font-weight:700;letter-spacing:-.8px}}.logo{{width:30px;height:28px}}.divider{{height:19px;width:1px;background:var(--line);margin:0 5px}}.product{{font-size:13px;font-weight:450;letter-spacing:-.1px}}.links{{display:flex;gap:24px;color:#555;font-size:12px}}.links a:hover,.blue{{color:var(--blue)}}.hero{{padding:105px 0 80px}}.kicker{{font:10px/1.4 var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}}h1{{font-size:clamp(54px,7vw,92px);font-weight:540;line-height:.96;letter-spacing:-5px;max-width:930px;margin:19px 0 27px}}.lede{{font-size:18px;line-height:1.65;color:var(--muted);max-width:680px}}.actions{{display:flex;gap:12px;margin-top:30px;flex-wrap:wrap}}.btn{{display:inline-flex;min-height:44px;align-items:center;padding:11px 18px;border-radius:var(--radius);font-size:12px;border:1px solid var(--line)}}.btn.primary{{background:var(--ink);color:white;border-color:var(--ink)}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}}.stat{{padding:28px 24px;border-right:1px solid var(--line)}}.stat:last-child{{border:0}}.stat b{{font-size:39px;font-weight:530;letter-spacing:-1.8px;display:block}}.stat span{{font-size:11px;color:var(--muted)}}section{{padding:72px 0}}.section-head{{display:flex;justify-content:space-between;gap:30px;align-items:end;margin-bottom:30px}}.section-head h2{{font-size:32px;line-height:1.15;letter-spacing:-1.2px;font-weight:550;margin:9px 0 0}}.section-head p{{color:var(--muted);font-size:12px;max-width:430px}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:16px}}.bench{{border:1px solid var(--line);border-radius:12px;padding:23px}}.bench-top{{display:flex;justify-content:space-between;gap:20px;align-items:start;margin-bottom:23px}}.bench h3{{font-size:21px;font-weight:540;letter-spacing:-.5px;margin:5px 0}}.delta{{font:14px var(--mono);color:#777}}.delta.up{{color:var(--blue)}}.delta.down{{color:#222}}.lane{{display:grid;grid-template-columns:55px 1fr 50px;align-items:center;gap:12px;margin:11px 0;font-size:11px}}.lane b{{font:12px var(--mono);text-align:right}}.track{{height:7px;background:#ededed;border-radius:1px;overflow:hidden}}.track i{{height:100%;display:block;background:#1d1d1d}}.track i.ours{{background:var(--blue)}}.bench p{{font-size:10px;color:var(--muted);margin:17px 0 0;border-top:1px solid var(--line);padding-top:13px}}.callout{{background:var(--blue-soft);padding:34px;border-left:3px solid var(--blue);font-size:17px;line-height:1.6}}.method{{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}}.method div{{background:white;padding:25px}}.method b{{display:block;font-size:14px;margin:7px 0}}.method p{{font-size:11px;color:var(--muted);margin:0}}footer{{border-top:1px solid var(--line);padding:28px 0 80px;display:flex;justify-content:space-between;gap:24px;color:#777;font-size:11px}}@media(max-width:720px){{.wrap{{width:min(100% - 32px,var(--page))}}.links a:not(:last-child){{display:none}}.hero{{padding:70px 0 55px}}h1{{letter-spacing:-3px}}.stats{{grid-template-columns:1fr 1fr}}.stat:nth-child(2){{border-right:0}}.stat:nth-child(-n+2){{border-bottom:1px solid var(--line)}}.grid,.method{{grid-template-columns:1fr}}.section-head,footer{{display:block}}.section-head p{{margin-top:15px}}}}
</style></head><body><header class="wrap nav"><a class="brand" href="/"><svg class="logo" viewBox="0 0 30 28" aria-hidden="true"><path d="M3 25A12 12 0 0 1 27 25" fill="none" stroke="#154cff" stroke-width="5"/><path d="M8 25a7 7 0 0 1 14 0" fill="none" stroke="#050505" stroke-width="4"/></svg><span>agi labs</span><i class="divider"></i><span class="product">Jev48</span></a><nav class="links"><a href="#results">Results</a><a href="#method">Method</a><a href="https://github.com/agilabs-ai/jev48">Source ↗</a></nav></header><main><div class="wrap hero"><div class="kicker"><span class="blue">●</span> OPEN REPRODUCTION · FINAL PUBLIC RUN</div><h1>Six benchmarks.<br><span class="blue">No hidden losses.</span></h1><p class="lede">We gave an AI agent 48 hours to reproduce TypeSafe’s Jev using public information and an open 2B model. This is the complete public scorecard—every eligible reproducible suite, including the regressions.</p><div class="actions"><a class="btn primary" href="#results">See every result</a><a class="btn" href="https://github.com/agilabs-ai/jev48/tree/main/receipts">Audit the receipts ↗</a></div></div><div class="stats"><div class="stat"><b>6</b><span>public benchmark suites</span></div><div class="stat"><b>{total:,}</b><span>evaluated decisions / cases</span></div><div class="stat"><b>{wins}</b><span>suite wins for Jev48</span></div><div class="stat"><b>&lt;$1</b><span>additional L40S benchmark spend</span></div></div><section class="wrap" id="results"><div class="section-head"><div><div class="kicker">COMPLETE SCORECARD</div><h2>Jev48 vs. published Jev results</h2></div><p>Accuracy is shown where it is the common metric. Protocol notes disclose paired, unpaired, and repeated-reference comparisons.</p></div><div class="grid">{table}</div></section><section class="wrap"><div class="callout"><b>Where it gets close:</b> Jev48 reaches the same ceiling on JevBench Easy, and the strongest additional suites test whether its open decision head can preserve that result across classification, code review, and contradiction detection. The page does not select only those favorable slices.</div></section><section class="wrap" id="method"><div class="section-head"><div><div class="kicker">AUDIT CONTRACT</div><h2>Claims trace back to the repository</h2></div><p>This page is generated from committed JSON summaries. Editing a number here means changing a receipt first.</p></div><div class="method"><div><span class="kicker">01 / FREEZE</span><b>Code before outcomes</b><p>Adapters were committed to main before the paid runs.</p></div><div><span class="kicker">02 / INCLUDE</span><b>Full suites only</b><p>No result-dependent subsets or hidden exclusions.</p></div><div><span class="kicker">03 / VERIFY</span><b>Immutable evidence</b><p>Model, source, script, and repository hashes ship with every receipt.</p></div></div><div class="actions"><a class="btn" href="https://github.com/agilabs-ai/jev48/blob/main/BENCHMARK_REGISTRY.md">Eligibility registry ↗</a><a class="btn" href="https://github.com/agilabs-ai/jev48/blob/main/RESULTS_PUBLIC.md">Full methodology ↗</a><a class="btn" href="https://github.com/agilabs-ai/jev48/blob/main/THIRD_PARTY_NOTICES.md">Licenses ↗</a></div></section></main><footer class="wrap"><div>AGI Labs · Jev48 · September 2026</div><div>Independent research. Not affiliated with TypeSafe.</div></footer></body></html>'''
 out=ROOT/"site/jev48/index.html"; out.parent.mkdir(parents=True,exist_ok=True); out.write_text(html_doc,encoding="utf-8")
 (out.parent/"benchmark-ranking.png").write_bytes((ROOT/"launch/benchmark-ranking.png").read_bytes())
 print(out)
if __name__=="__main__": main()
